import React, { useState, useEffect } from 'react';

function Analytics() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("ALL");

  useEffect(() => {
    fetch('http://localhost:5000/api/analytics')
      .then(r => r.json())
      .then(d => {
        setData(d);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  if (loading) return <p>Loading...</p>;
  if (!data) return <p style={{ color: 'red' }}>Start backend server.</p>;

  const maxDefects = Math.max(...data.stageData.map(s => s.defects), 1);

  // ✅ Filter UAVs
  const filteredUAVs = data.uavs?.filter(u => {
    if (filter === "ALL") return true;
    return u.status === filter;
  }) || [];

  return (
    <div>
      <h2>Analytics</h2>

      {/* ✅ KPI Cards (Clickable) */}
      <div style={{ display: 'flex', gap: '12px', margin: '12px 0', flexWrap: 'wrap' }}>
        {[
          { label: 'Total', value: data.total, color: 'blue', type: 'ALL' },
          { label: 'Passed', value: data.passed, color: 'green', type: 'Passed' },
          { label: 'Failed', value: data.failed, color: 'red', type: 'Failed' },
          { label: 'In Progress', value: data.inProgress, color: 'orange', type: 'In Progress' },
          { label: 'Pass Rate', value: data.passRate + '%', color: 'purple', type: 'ALL' },
        ].map(k => (
          <div
            key={k.label}
            onClick={() => setFilter(k.type)}
            style={{
              border: '2px solid ' + k.color,
              padding: '10px 16px',
              borderRadius: '6px',
              textAlign: 'center',
              cursor: 'pointer',
              background: filter === k.type ? '#e6f0ff' : 'white',
              transition: '0.2s'
            }}
          >
            <div style={{ fontSize: '24px', fontWeight: 'bold', color: k.color }}>
              {k.value}
            </div>
            <div style={{ fontSize: '12px' }}>{k.label}</div>
          </div>
        ))}
      </div>

      {data.total === 0 ? (
        <p>No data yet. Add UAVs first.</p>
      ) : (
        <>
          {/* ✅ Defects Chart */}
          <div style={{ border: '1px solid #ddd', borderRadius: '6px', padding: '14px', marginBottom: '16px' }}>
            <h3>Defects Per Stage</h3>

            {data.stageData.map(s => (
              <div key={s.name} style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '8px' }}>
                <span style={{ width: '200px' }}>{s.name}</span>

                <div style={{ flex: 1, background: '#eee', height: '20px', borderRadius: '4px' }}>
                  <div style={{
                    width: (s.defects / maxDefects) * 100 + '%',
                    background: s.defects > 3 ? 'red' : s.defects > 0 ? 'orange' : '#eee',
                    height: '20px',
                    borderRadius: '4px',
                    color: 'white',
                    paddingLeft: '6px',
                    display: 'flex',
                    alignItems: 'center'
                  }}>
                    {s.defects > 0 ? s.defects : ''}
                  </div>
                </div>

                <span style={{ fontSize: '12px' }}>
                  D:{s.defects} R:{s.rework} F:{s.failed}
                </span>
              </div>
            ))}
          </div>

          {/* ✅ Stage Health Table */}
          <div style={{ border: '1px solid #ddd', borderRadius: '6px', padding: '14px', marginBottom: '16px' }}>
            <h3>Stage Health</h3>

            <table border="1" cellPadding="8" style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead style={{ background: '#333', color: 'white' }}>
                <tr>
                  <th>Stage</th>
                  <th>Defects</th>
                  <th>Rework</th>
                  <th>Failures</th>
                  <th>Health</th>
                </tr>
              </thead>
              <tbody>
                {data.stageData.map(s => {
                  const health =
                    s.defects === 0 ? 'Good' :
                    s.defects <= 2 ? 'Monitor' : 'Critical';

                  const color =
                    s.defects === 0 ? 'green' :
                    s.defects <= 2 ? 'orange' : 'red';

                  return (
                    <tr key={s.name}>
                      <td>{s.name}</td>
                      <td style={{ color: s.defects > 0 ? 'red' : 'green' }}>{s.defects}</td>
                      <td style={{ color: s.rework > 0 ? 'orange' : 'green' }}>{s.rework}</td>
                      <td style={{ color: s.failed > 0 ? 'red' : 'green' }}>{s.failed}</td>
                      <td style={{ color, fontWeight: 'bold' }}>{health}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          {/* ✅ Technician Table */}
          {data.techStats?.length > 0 && (
            <div style={{ border: '1px solid #ddd', borderRadius: '6px', padding: '14px' }}>
              <h3>Technician Performance</h3>

              <table border="1" cellPadding="8" style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead style={{ background: '#333', color: 'white' }}>
                  <tr>
                    <th>Technician</th>
                    <th>Total</th>
                    <th>Passed</th>
                    <th>Defects</th>
                    <th>Pass Rate</th>
                  </tr>
                </thead>
                <tbody>
                  {data.techStats.map(t => {
                    const rate = t.total > 0 ? Math.round((t.passed / t.total) * 100) : 0;

                    return (
                      <tr key={t.techId}>
                        <td>{t.techId}</td>
                        <td>{t.total}</td>
                        <td style={{ color: 'green' }}>{t.passed}</td>
                        <td style={{ color: t.defects > 0 ? 'red' : 'green' }}>{t.defects}</td>
                        <td style={{
                          color: rate >= 80 ? 'green' : rate >= 50 ? 'orange' : 'red',
                          fontWeight: 'bold'
                        }}>
                          {rate}%
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}

          {/* ✅ UAV STATUS TABLE (NEW FEATURE) */}
          <div style={{ border: '1px solid #ddd', borderRadius: '6px', padding: '14px', marginTop: '20px' }}>
            <h3>UAV List ({filter})</h3>

            <table border="1" cellPadding="8" style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead style={{ background: '#333', color: 'white' }}>
                <tr>
                  <th>UAV ID</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {filteredUAVs.map(u => (
                  <tr key={u.id}>
                    <td>{u.id}</td>
                    <td style={{
                      color:
                        u.status === 'Passed' ? 'green' :
                        u.status === 'Failed' ? 'red' : 'orange',
                      fontWeight: 'bold'
                    }}>
                      {u.status}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

        </>
      )}
    </div>
  );
}

export default Analytics;
